def resolve_enrichment_rscript():
    runtime_r_root = WORKSPACE_ROOT / "runtime" / "R"
    versioned_rscripts = sorted(runtime_r_root.glob("R-*/bin/Rscript.exe"), reverse=True) if runtime_r_root.exists() else []
    candidates = [
        *versioned_rscripts,
        WORKSPACE_ROOT / "runtime" / "R" / "bin" / "Rscript.exe",
        WORKSPACE_ROOT / "runtime" / "R" / "Rscript.exe",
        WORKSPACE_ROOT / "R" / "bin" / "Rscript.exe",
        WORKSPACE_ROOT / "R" / "Rscript.exe",
    ]
    for candidate in candidates:
        if candidate.exists():
            return str(candidate)
    return "Rscript"


def safe_console_print(*args, sep=" ", end="\n", flush=False):
    text = sep.join(str(arg) for arg in args) + end
    stream = sys.stdout
    try:
        stream.write(text)
    except UnicodeEncodeError:
        encoding = getattr(stream, "encoding", None) or "utf-8"
        safe_text = text.encode(encoding, errors="replace").decode(encoding, errors="replace")
        stream.write(safe_text)
    if flush:
        stream.flush()


LOG_ICON_PREFIX_RE = re.compile(r"^\s*(?:[\U0001F300-\U0001FAFF]|[\u2600-\u27BF]|\ufe0f|\u200d)+\s*")


def sanitize_log_message(msg):
    text = str(msg)
    for _ in range(4):
        cleaned = LOG_ICON_PREFIX_RE.sub("", text)
        if cleaned == text:
            break
        text = cleaned
    return text


